   110  static int
   111  coolkey_find_matching_cert(sc_card_t *card, sc_cardctl_coolkey_object_t *in_obj, sc_cardctl_coolkey_object_t **cert_obj) {
   112          sc_cardctl_coolkey_find_object_t fobj;
   113          sc_cardctl_coolkey_attribute_t template[2];
   114          u8 obj_class[4];
   115          int r;
   116
   117          /* we are searching for certs .. */
   118          template[0].attribute_type = CKA_CLASS;
   119          template[0].attribute_data_type = SC_CARDCTL_COOLKEY_ATTR_TYPE_ULONG;
   120          template[0].attribute_length = sizeof(obj_class);
   121          template[0].attribute_value = obj_class;
   122          ulong2bebytes(obj_class, CKO_CERTIFICATE);
   123
   124          /* fetch the current object's CKA_ID */
   125          template[1].attribute_type = CKA_ID;
   126          template[1].object = in_obj;
   127          r = sc_card_ctl(card, SC_CARDCTL_COOLKEY_GET_ATTRIBUTE, &template[1]);
   128          if (r < 0) {
   129                  return r;
   130          }
   131          template[0].object = NULL; /*paranoia */
   132          template[1].object = NULL; /*paranoia */
   133
   134          /* now find the cert that has the ID */
   135          fobj.type = SC_CARDCTL_COOLKEY_FIND_BY_TEMPLATE;
   136          fobj.obj = NULL;
   137          fobj.coolkey_template = &template[0];
   138          fobj.template_count=2;
   139          r = sc_card_ctl(card, SC_CARDCTL_COOLKEY_FIND_OBJECT, &fobj);
   140          if (r < 0) {
   141                  return r;
   142          }
   143          *cert_obj = fobj.obj;
   144          return SC_SUCCESS;
   145  }
