   461  static int sc_pkcs15emu_coolkey_init(sc_pkcs15_card_t *p15card)
   462  {
   463          static const pindata pins[] = {
   464                  { "1", NULL, "", 0x00,
   465                    SC_PKCS15_PIN_TYPE_ASCII_NUMERIC,
   466                    32, 4, 32,
   467                    SC_PKCS15_PIN_FLAG_INITIALIZED,
   468                    -1, 0xFF,
   469                    SC_PKCS15_CO_FLAG_PRIVATE },
   470                  { NULL, NULL, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 0}
   471          };
   472
   473          /*
   474           * The size of the key or the algid is not really known
   475           * but can be derived from the certificates.
   476           * the cert, pubkey and privkey are a set.
   477           * Key usages bits taken from certificate key usage extension.
   478           */
   479
   480          int    r, i;
   481          sc_card_t *card = p15card->card;
   482          sc_serial_number_t serial;
   483          int count;
   484          struct sc_pkcs15_object *obj;
   485
   486          SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);
   487
   488          memset(&serial, 0, sizeof(serial));
   489
   490          /* coolkey caches a nonce once it logs in, don't keep the pin around. The card will
   491           * stay logged in until it's been pulled from the reader, in which case you want to reauthenticate
   492           * anyway */
   493          p15card->opts.use_pin_cache = 0;
   494
   495
   496          /* get the token info from the card */
   497          r = sc_card_ctl(card, SC_CARDCTL_COOLKEY_GET_TOKEN_INFO, p15card->tokeninfo);
   498          if (r < 0) {
   499                  /* put some defaults in if we didn't succeed */
   500                  p15card->tokeninfo->label = strdup("Coolkey");
   501                  p15card->tokeninfo->manufacturer_id = strdup("Unknown");
   502                  p15card->tokeninfo->serial_number = strdup("00000000");
   503          }
   504
   505          /* set pins */
   506          sc_log(card->ctx,  "Coolkey adding pins...");
   507          for (i = 0; pins[i].id; i++) {
   508                  struct sc_pkcs15_auth_info pin_info;
   509                  struct sc_pkcs15_object   pin_obj;
   510                  const char * label;
   511
   512                  memset(&pin_info, 0, sizeof(pin_info));
   513                  memset(&pin_obj,  0, sizeof(pin_obj));
   514
   515                  pin_info.auth_type = SC_PKCS15_PIN_AUTH_TYPE_PIN;
   516                  sc_pkcs15_format_id(pins[i].id, &pin_info.auth_id);
   517                  pin_info.attrs.pin.reference     = pins[i].ref;
   518                  pin_info.attrs.pin.flags         = pins[i].flags;
   519                  pin_info.attrs.pin.type          = pins[i].type;
   520                  pin_info.attrs.pin.min_length    = pins[i].minlen;
   521                  pin_info.attrs.pin.stored_length = pins[i].storedlen;
   522                  pin_info.attrs.pin.max_length    = pins[i].maxlen;
   523                  pin_info.attrs.pin.pad_char      = pins[i].pad_char;
   524                  sc_format_path(pins[i].path, &pin_info.path);
   525                  pin_info.tries_left    = -1;
   526
   527                  label = pins[i].label? pins[i].label : p15card->tokeninfo->label;
   528                  sc_log(card->ctx,  "Coolkey Adding pin %d label=%s",i, label);
   529                  strncpy(pin_obj.label, label, SC_PKCS15_MAX_LABEL_SIZE - 1);
   530                  pin_obj.flags = pins[i].obj_flags;
   531
   532                  r = sc_pkcs15emu_add_pin_obj(p15card, &pin_obj, &pin_info);
   533                  if (r < 0)
   534                          LOG_FUNC_RETURN(card->ctx, r);
   535          }
   536
   537          /* set other objects */
   538          r = (card->ops->card_ctl)(card, SC_CARDCTL_COOLKEY_INIT_GET_OBJECTS, &count);
   539          LOG_TEST_RET(card->ctx, r, "Can not initiate objects.");
   540
   541          for (i = 0; i < count; i++) {
   542                  struct sc_cardctl_coolkey_object     coolkey_obj;
   543                  struct sc_pkcs15_object    obj_obj;
   544                  struct sc_pkcs15_cert_info cert_info;
   545                  struct sc_pkcs15_pubkey_info pubkey_info;
   546                  struct sc_pkcs15_prkey_info prkey_info;
   547                  sc_pkcs15_pubkey_t *key = NULL;
   548                  void *obj_info = NULL;
   549                  int obj_type = 0;
   550                  CK_KEY_TYPE key_type;
   551                  CK_OBJECT_CLASS obj_class;
   552                  size_t len;
   553
   554                  r = (card->ops->card_ctl)(card, SC_CARDCTL_COOLKEY_GET_NEXT_OBJECT, &coolkey_obj);
   555                  if (r < 0)
   556                          LOG_FUNC_RETURN(card->ctx, r);
   557
   558
   559                  memset(&obj_obj, 0, sizeof(obj_obj));
   560                  /* coolkey applets have label only on the certificates,
   561                   * but we should copy it also to the keys matching the same ID */
   562                  coolkey_get_attribute_bytes(card, &coolkey_obj, CKA_LABEL, (u8 *)obj_obj.label, &len, sizeof(obj_obj.label));
   563                  coolkey_get_flags(card, &coolkey_obj, &obj_obj.flags);
   564                  if (obj_obj.flags & SC_PKCS15_CO_FLAG_PRIVATE) {
   565                          sc_pkcs15_format_id(pins[0].id, &obj_obj.auth_id);
   566                  }
   567
   568                  r = coolkey_get_attribute_ulong(card, &coolkey_obj, CKA_CLASS, &obj_class);
   569                  if (r < 0) {
   570                          goto fail;
   571                  }
   572                  switch (obj_class) {
   573                  case CKO_PRIVATE_KEY:
   574                          r = coolkey_get_attribute_ulong(card, &coolkey_obj, CKA_KEY_TYPE, &key_type);
   575                          /* default to CKK_RSA */
   576                          if (r == SC_ERROR_DATA_OBJECT_NOT_FOUND) {
   577                                  key_type = CKK_RSA;
   578                                  r = SC_SUCCESS;
   579                          }
   580                          if (r < 0) {
   581                                  goto fail;
   582                          }
   583                          /* set the info values */
   584                          obj_info = &prkey_info;
   585                          memset(&prkey_info, 0, sizeof(prkey_info));
   586                          coolkey_get_id(card, &coolkey_obj, &prkey_info.id);
   587                          prkey_info.path = coolkey_obj.path;
   588                          prkey_info.key_reference = coolkey_obj.id;
   589                          prkey_info.native = 1;
   590                          coolkey_get_usage(card, &coolkey_obj, &prkey_info.usage);
   591                          coolkey_get_access(card, &coolkey_obj, &prkey_info.access_flags);
   592                          key = coolkey_get_public_key(p15card, &coolkey_obj, key_type);
   593                          if (key_type == CKK_RSA) {
   594                                  obj_type = SC_PKCS15_TYPE_PRKEY_RSA;
   595                                  if (key) {
   596                                          prkey_info.modulus_length =  key->u.rsa.modulus.len*8;
   597                                  }
   598                          } else if (key_type == CKK_EC) {
   599                                  obj_type = SC_PKCS15_TYPE_PUBKEY_EC;
   600                                  if (key) {
   601                                          prkey_info.field_length =  key->u.ec.params.field_length;
   602                                  }
   603                          } else {
   604                                  goto fail;
   605                          }
   606                          break;
   607
   608                  case CKO_PUBLIC_KEY:
   609                          r = coolkey_get_attribute_ulong(card, &coolkey_obj, CKA_KEY_TYPE, &key_type);
   610                          /* default to CKK_RSA */
   611                          if (r == SC_ERROR_DATA_OBJECT_NOT_FOUND) {
   612                                  key_type = CKK_RSA;
   613                                  r = SC_SUCCESS;
   614                          }
   615                          if (r < 0) {
   616                                  goto fail;
   617                          }
   618                          key = coolkey_get_public_key(p15card, &coolkey_obj, key_type);
   619                          if (key == NULL) {
   620                                  goto fail;
   621                          }
   622                          /* set the info values */
   623                          obj_info = &pubkey_info;
   624                          memset(&pubkey_info, 0, sizeof(pubkey_info));
   625                          r = sc_pkcs15_encode_pubkey_as_spki(card->ctx, key, &pubkey_info.direct.spki.value,
   626                                                                                                                                                          &pubkey_info.direct.spki.len);
   627                          if (r < 0)
   628                                  goto fail;
   629                          coolkey_get_id(card, &coolkey_obj, &pubkey_info.id);
   630                          pubkey_info.path = coolkey_obj.path;
   631                          pubkey_info.native        = 1;
   632                          pubkey_info.key_reference = coolkey_obj.id;
   633                          coolkey_get_usage(card, &coolkey_obj, &pubkey_info.usage);
   634                          coolkey_get_access(card, &coolkey_obj, &pubkey_info.access_flags);
   635                          if (key_type == CKK_RSA) {
   636                                  obj_type = SC_PKCS15_TYPE_PUBKEY_RSA;
   637                                  pubkey_info.modulus_length =  key->u.rsa.modulus.len*8;
   638                          } else if (key_type == CKK_EC) {
   639                                  obj_type = SC_PKCS15_TYPE_PUBKEY_EC;
   640                                  pubkey_info.field_length =  key->u.ec.params.field_length;
   641                          } else {
   642                                  goto fail;
   643                          }
   644                          /* set the obj values */
   645                          obj_obj.emulated = key;
   646                          key = NULL;
   647                          break;
   648
   649                  case CKO_CERTIFICATE:
   650                          obj_info = &cert_info;
   651                          memset(&cert_info, 0, sizeof(cert_info));
   652                          coolkey_get_id(card, &coolkey_obj, &cert_info.id);
   653                          cert_info.path = coolkey_obj.path;
   654                          obj_type = SC_PKCS15_TYPE_CERT_X509;
   655
   656                          /* following will find the cached cert in cert_info */
   657                          r = coolkey_get_certificate(card, &coolkey_obj, &cert_info.value);
   658                          if (r < 0) {
   659                                  goto fail;
   660                          }
   661                          break;
   662
   663
   664                  default:
   665                          /* no other recognized types which are stored 'on card' */
   666                          break;
   667                  }
   668                  if (obj_info == NULL) {
   669                          continue;
   670                  }
   671
   672                  r = sc_pkcs15emu_object_add(p15card, obj_type, &obj_obj, obj_info);
   673                  if (r != SC_SUCCESS)
   674                          sc_log(card->ctx, "sc_pkcs15emu_object_add() returned %d", r);
   675  fail:
   676                  if (key) { sc_pkcs15_free_pubkey(key); }
   677
   678          }
   679          r = (card->ops->card_ctl)(card, SC_CARDCTL_COOLKEY_FINAL_GET_OBJECTS, &count);
   680          LOG_TEST_RET(card->ctx, r, "Can not finalize objects.");
   681
   682          /* Iterate over all the created objects and fill missing labels */
   683          for (obj = p15card->obj_list; obj != NULL; obj = obj->next) {
   684                  struct sc_pkcs15_id *id = NULL;
   685                  struct sc_pkcs15_object *cert_object;
   686
   687                  /* label non-empty -- do not overwrite */
   688                  if (obj->label[0] != '\0')
   689                          continue;
   690
   691                  switch (obj->type & SC_PKCS15_TYPE_CLASS_MASK) {
   692                  case SC_PKCS15_TYPE_PUBKEY:
   693                          id = &((struct sc_pkcs15_pubkey_info *)obj->data)->id;
   694                          break;
   695                  case SC_PKCS15_TYPE_PRKEY:
   696                          id = &((struct sc_pkcs15_prkey_info *)obj->data)->id;
   697                          break;
   698                  default:
   699                          /* We do not care about other objects */
   700                          continue;
   701                  }
   702                  r = sc_pkcs15_find_cert_by_id(p15card, id, &cert_object);
   703                  if (r != 0)
   704                          continue;
   705
   706                  sc_log(card->ctx, "Copy label \"%s\" from cert to key object",
   707                          cert_object->label);
   708                  memcpy(obj->label, cert_object->label, SC_PKCS15_MAX_LABEL_SIZE);
   709          }
   710
   711          LOG_FUNC_RETURN(card->ctx, SC_SUCCESS);
   712  }
