   869  static const unsigned int
   870  coolkey_number_of_error_codes = sizeof(coolkey_error_codes)/sizeof(coolkey_error_codes[0]);
   871
   872  static int coolkey_check_sw(sc_card_t *card, unsigned int sw1, unsigned int sw2)
   873  {
   874          sc_log(card->ctx,
   875                  "sw1 = 0x%02x, sw2 = 0x%02x\n", sw1, sw2);
   876
   877          if (sw1 == 0x90 && sw2 == 0x00)
   878                  return SC_SUCCESS;
   879
   880          if (sw1 == 0x9c) {
   880          if (sw1 == 0x9c) {
   881                  if (sw2 == 0xff) {
   882                          /* shouldn't happen on a production applet, 0x9cff is a debugging error code */
   883                          return SC_ERROR_INTERNAL;
   884                  }
   885                  if (sw2 >= coolkey_number_of_error_codes) {
   886                          return SC_ERROR_UNKNOWN;
   887                  }
   888                  return coolkey_error_codes[sw2].sc_error;
   889          }
   890
   891          /* iso error */
   892          return sc_get_iso7816_driver()->ops->check_sw(card, sw1, sw2);
   893  }
