   895  /*
   896   * Send a command and receive data.
   897   *
   898   * A caller may provide a buffer, and length to read. If not provided,
   899   * an internal 4096 byte buffer is used, and a copy is returned to the
   900   * caller. that need to be freed by the caller.
   901   *
   902   * modelled after a similar function in card-piv.c. The coolkey version
   903   * adds the coolkey nonce to user authenticated operations.
   904   */
   905
   906  static int coolkey_apdu_io(sc_card_t *card, int cla, int ins, int p1, int p2,
   907          const u8 * sendbuf, size_t sendbuflen, u8 ** recvbuf, size_t * recvbuflen,
   908          const u8 *nonce, size_t nonce_len)
   909  {
   910          int r;
   911          sc_apdu_t apdu;
   912          u8 rbufinitbuf[COOLKEY_MAX_SIZE];
   913          u8 rsendbuf[COOLKEY_MAX_SIZE];
   914          u8 *rbuf;
   915          size_t rbuflen;
   916          int cse = 0;
   917
   918
   919          SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);
   920
   921          sc_log(card->ctx,
   922                   "%02x %02x %02x %"SC_FORMAT_LEN_SIZE_T"u : %"SC_FORMAT_LEN_SIZE_T"u %"SC_FORMAT_LEN_SIZE_T"u\n",
   923                   ins, p1, p2, sendbuflen, card->max_send_size,
   924                   card->max_recv_size);
   925
   926          rbuf = rbufinitbuf;
   927          rbuflen = sizeof(rbufinitbuf);
   928
   929          /* if caller provided a buffer and length */
   930          if (recvbuf && *recvbuf && recvbuflen && *recvbuflen) {
   931                  rbuf = *recvbuf;
   932                  rbuflen = *recvbuflen;
   933          }
   934
   935          if (sendbuf || nonce) {
   936                  if (recvbuf) {
   937                          cse = SC_APDU_CASE_4_SHORT;
   938                  } else {
   939                          cse = SC_APDU_CASE_3_SHORT;
   940                  }
   941          } else {
   942                  if (recvbuf) {
   943                          cse = SC_APDU_CASE_2_SHORT;
   944                  } else {
   945                          cse = SC_APDU_CASE_1;
   946                  }
   947          }
   948
   949          /* append the nonce if we have it. Coolkey just blindly puts this at the end
   950           * of the APDU (while adjusting lc). This converts case 1 to case 3. coolkey
   951           * also always drops le in case 4 (which happens when proto = T0). nonces are
   952           * never used on case 2 commands, so we can simply append the nonce to the data
   953           * and we should be fine */
   954          if (nonce) {
   955                  u8 *buf = rsendbuf;
   956                  if (sendbuf) {
   957                          sendbuflen = MIN(sendbuflen,sizeof(rsendbuf)-nonce_len);
   958                          memcpy(rsendbuf, sendbuf, sendbuflen);
   959                          buf += sendbuflen;
   960                  }
   961                  memcpy(buf, nonce, nonce_len);
   962                  sendbuflen += nonce_len;
   963                  sendbuf =rsendbuf;
   964          }
   965
   966          sc_format_apdu(card, &apdu, cse, ins, p1, p2);
   967
   968          apdu.lc = sendbuflen;
   969          apdu.datalen = sendbuflen;
   970          apdu.data = sendbuf;
   971
   972
   973          /* coolkey uses non-standard classes */
   974          apdu.cla = cla;
   975
   976          if (recvbuf) {
   977                  apdu.resp = rbuf;
   978                  apdu.le = (rbuflen > 255) ? 255 : rbuflen;
   979                  apdu.resplen = rbuflen;
   980          } else {
   981                   apdu.resp =  rbuf;
   982                   apdu.le = 0;
   983                   apdu.resplen = 0;
   984          }
   985
   986          sc_log(card->ctx,
   987                   "calling sc_transmit_apdu flags=%lx le=%"SC_FORMAT_LEN_SIZE_T"u, resplen=%"SC_FORMAT_LEN_SIZE_T"u, resp=%p",
   988                   apdu.flags, apdu.le, apdu.resplen, apdu.resp);
   989
   990          /* with new adpu.c and chaining, this actually reads the whole object */
   991          r = sc_transmit_apdu(card, &apdu);
   992
   993          sc_log(card->ctx,
   994                   "result r=%d apdu.resplen=%"SC_FORMAT_LEN_SIZE_T"u sw1=%02x sw2=%02x",
   995                   r, apdu.resplen, apdu.sw1, apdu.sw2);
   996
   997          if (r < 0) {
   998                  sc_log(card->ctx, "Transmit failed");
   999                  goto err;
  1000          }
  1001          r = sc_check_sw(card, apdu.sw1, apdu.sw2);
  1002          if (r < 0) {
  1003                  sc_log(card->ctx, "Transmit failed");
  1004                  goto err;
  1005          }
  1006
  1007          if (recvbuflen) {
  1008                  if (recvbuf && *recvbuf == NULL) {
  1009                          *recvbuf =  malloc(apdu.resplen);
  1010                          if (*recvbuf == NULL) {
  1011                                  r = SC_ERROR_OUT_OF_MEMORY;
  1012                                  goto err;
  1013                          }
  1014                          memcpy(*recvbuf, rbuf, apdu.resplen);
  1015                  }
  1016                  *recvbuflen =  apdu.resplen;
  1017                  r = *recvbuflen;
  1018          }
  1019
  1020  err:
  1021          LOG_FUNC_RETURN(card->ctx, r);
  1022  }
