  1038                          NULL, 0, &receive_buf, &receive_len, NULL, 0);
  1039          if (len == sizeof(*life_cycle)) {
  1040                  return SC_SUCCESS;
  2200          }
  2201          /* if we didn't pull the cuid from the combined object, then grab it now */
  2202          if (!combined_processed) {
  2203                  global_platform_cplc_data_t cplc_data;
  2204                  /* select the card manager, because a card with applet only will have
  2205                     already selected the coolkey applet */
  2206
  2207                  r = gp_select_card_manager(card);
  2208                  if (r < 0) {
  2209                          goto cleanup;
  2210                  }
  2211
  2212                  r = gp_get_cplc_data(card, &cplc_data);
  2213                  if (r < 0) {
  2214                          goto cleanup;
  2215                  }
  2216                  coolkey_make_cuid_from_cplc(&priv->cuid, &cplc_data);
  2217                  priv->token_name = (u8 *)strdup("COOLKEY");
  2218                  if (priv->token_name == NULL) {
  2219                          r= SC_ERROR_OUT_OF_MEMORY;
  2220                          goto cleanup;
