  2222                  priv->token_name_length = sizeof("COOLKEY")-1;
  2223          }
  2224          card->drv_data = priv;
  2225          return SC_SUCCESS;
  2226
  2227  cleanup:
  2228          if (priv) {
  2229                  coolkey_free_private_data(priv);
  2230          }
  2231          return r;
  2232  }
