  2235  /* NOTE: returns a bool, 1 card matches, 0 it does not */
  2236  static int coolkey_match_card(sc_card_t *card)
  2237  {
  2238          int r;
  2239
  2240          SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);
  2241          /* Since we send an APDU, the card's logout function may be called...
  2242           * however it may be in dirty memory */
  2243          card->ops->logout = NULL;
  2244
  2245          r = coolkey_select_applet(card);
  2246          if (r == SC_SUCCESS) {
  2247                  sc_apdu_t apdu;
  2248
  2249                  /* The GET STATUS INS with P1 = 1 returns invalid instruction (0x6D00)
  2250                   * on Coolkey applet (reserved for GetMemory function),
  2251                   * while incorrect P1 (0x9C10) on Muscle applets
  2252                   */
  2253                  sc_format_apdu(card, &apdu, SC_APDU_CASE_1, COOLKEY_INS_GET_STATUS, 0x01, 0x00);
  2254                  apdu.cla = COOLKEY_CLASS;
  2255                  apdu.le = 0x00;
  2256                  apdu.resplen = 0;
  2257                  apdu.resp = NULL;
  2258                  r = sc_transmit_apdu(card, &apdu);
  2259                  if (r == SC_SUCCESS && apdu.sw1 == 0x6d && apdu.sw2 == 0x00) {
  2260                          return 1;
  2261                  }
  2262                  return 0;
  2263          }
  2264          return 0;
  2265  }
